// Merge into JUNIOR_RESULTS_DATA.results on load, update stageStatus
(function(){
  if (!window.JUNIOR_RESULTS_DATA) return;
  var D = window.JUNIOR_RESULTS_DATA;
  D.results = (D.results || []).concat(window.CENTRAL_EWC_RESULTS.results);
  // Update stageStatus to reflect Central loaded
  if (D.meta && Array.isArray(D.meta.stageStatus)) {
    var entry = D.meta.stageStatus.find(function(s){ return s.stage === 'E/W/C'; });
    if (entry) {
      entry.status = 'partial';
      entry.description = 'Central loaded (' + window.CENTRAL_EWC_RESULTS.meta.rows + ' rows, ' + window.CENTRAL_EWC_RESULTS.meta.athletes + ' athletes); East and West pending';
    }
  }
  console.log('[ewc-central] merged', window.CENTRAL_EWC_RESULTS.results.length, 'Central results into JUNIOR_RESULTS_DATA');
})();
